/**
 * Test flow for slaPercentageTimer action
 * Demonstrates creating an SLA percentage timer
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testSlaPercentageTimer = Flow(
    {
        $id: Now.ID['test_sla_percentage_timer_flow'],
        name: 'Test SLA Percentage Timer',
        description: 'Tests the slaPercentageTimer core action with SLA task trigger',
    },
    wfa.trigger(trigger.application.slaTask, { $id: Now.ID['test_sla_percentage_timer_trigger'] }, {}),
    (_params) => {
        const result = wfa.action(
            action.core.slaPercentageTimer,
            { $id: Now.ID['test_sla_percentage_timer_action'] },
            {
                percentage: 75,
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_sla_percentage_timer_log'] },
            {
                log_level: 'info',
                log_message: `slaPercentageTimer outputs: status=${wfa.dataPill(result.status, 'string')}`,
            }
        )
    }
)
